    { passCount: 10, totalTests: 10 },
    { passCount: 5, totalTests: 10 },
    { passCount: 0, totalTests: 10 }
];

function classifyRun(run) {
    if (run.passCount === run.totalTests) {
        return "ALL_PASSED";
    } else if (run.passCount > 0) {
        return "PARTIAL";
    } else {
